import { ScrollArea } from 'moru-ui'

export function ActivityList() {
  return (
    <ScrollArea aria-label="Recent activity" style={{ height: 200 }}>
      <ol>
        {Array.from({ length: 20 }, (_, index) => (
          <li key={index} style={{ paddingBlock: 8 }}>
            Activity {index + 1}
          </li>
        ))}
      </ol>
    </ScrollArea>
  )
}

